const getOddCollatz = (n) => {
  const sequence = [n];
  while (n !== 1) {
    if (n % 2 === 0) {
      n = n / 2;
    } else {
      n = 3 * n + 1;
    }
    sequence.push(n);
  }
  const oddNumbers = sequence.filter(x => x % 2 !== 0);
  return oddNumbers.sort((a, b) => a - b);
};

